package com.gk.jobhelper.service;
import com.gk.jobhelper.dto.*;import com.gk.jobhelper.mapper.*;import org.junit.jupiter.api.Test;import org.springframework.transaction.support.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class RecruitmentPositionServiceBodyTest {
 @Test void repeatedBodyExtractionReplacesOnlyPreviousBodyPositions(){RecruitmentNoticeService notices=mock(RecruitmentNoticeService.class);RecruitmentAttachmentMapper attachments=mock(RecruitmentAttachmentMapper.class);RecruitmentPositionMapper positions=mock(RecruitmentPositionMapper.class);RecruitmentAttachmentDownloadService downloader=mock(RecruitmentAttachmentDownloadService.class);TransactionTemplate transactions=mock(TransactionTemplate.class);RecruitmentNoticeVO notice=new RecruitmentNoticeVO();notice.setDetailStatus("FETCHED");notice.setBodyHtml("<table><tr><th>岗位</th><th>人数</th><th>学历</th></tr><tr><td>工程师</td><td>2</td><td>本科</td></tr></table>");when(notices.detail(1L)).thenReturn(notice);when(transactions.execute(any())).thenAnswer(call->((TransactionCallback<?>)call.getArgument(0)).doInTransaction(null));RecruitmentPositionService service=new RecruitmentPositionService(notices,attachments,positions,downloader,java.util.Collections.emptyList(),new HtmlRecruitmentPositionExtractor(new RecruitmentExcelHeaderNormalizer()),transactions);assertEquals(1,service.extractBody(1L).getPositionCount());assertEquals(1,service.extractBody(1L).getPositionCount());verify(positions,times(2)).deleteBodyByNoticeId(1L);verify(positions,times(2)).insertBatch(argThat(list->list.size()==1&&list.get(0).getSourceAttachmentId()==null));}
}
